    for(double rate:{44100.0,48000.0,96000.0})for(float curve:{-1.0f,0.0f,1.0f}){AnalogueEnvelope env;for(int i=0;i<int(rate*.025);++i)env.next(false,rate,.01f,.02f,.3f,.02f,.03f,curve,curve,curve);need(std::abs(env.level-1)<.00001,"hold stays at full level after attack");for(int i=0;i<int(rate*.045);++i)env.next(false,rate,.01f,.02f,.3f,.02f,.03f,curve,curve,curve);need(std::abs(env.level-.3f)<.00001,"hold enters decay then exact sustain");for(int i=0;i<int(rate*.021)+3;++i)env.next(true,rate,.01f,.02f,.3f,.02f,.03f,curve,curve,curve);need(env.level==0,"contoured release reaches zero");}
