    const auto fixtureFolder=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("InfinityConcertPitch",{},false);fixtureFolder.createDirectory();const auto fixture=fixtureFolder.getChildFile("A440.wav");juce::AudioBuffer<float> sine(1,48000);for(int n=0;n<48000;++n)sine.setSample(0,n,.5f*std::sin(juce::MathConstants<double>::twoPi*440*n/48000));{auto stream=fixture.createOutputStream();juce::WavAudioFormat wav;std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(stream.get(),48000,1,24,{},0));need(writer!=nullptr,"concert-pitch fixture writer");stream.release();need(writer->writeFromAudioSampleBuffer(sine,0,48000),"concert-pitch fixture samples");}auto tuned=std::make_unique<SpaceInfinityProcessor>();clean(*tuned);need(tuned->importSample(fixture).wasOk(),"concert-pitch fixture import");set(*tuned,"source",3);set(*tuned,"sampleRoot",69);set(*tuned,"sampleLoop",1);set(*tuned,"concertPitch",442);set(*tuned,"routeA",0);tuned->prepareToPlay(48000,128);juce::AudioBuffer<float> tunedAudio(2,128);int firstCross=-1,lastCross=-1,crossings=0;float previous=0;for(int block=0;block<220;++block){juce::MidiBuffer midi;if(block==0)midi.addEvent(juce::MidiMessage::noteOn(1,69,.8f),0);tuned->processBlock(tunedAudio,midi);for(int n=0;n<128;++n){const float value=tunedAudio.getSample(0,n);if(block>30&&value>=0&&previous<0){const int sample=block*128+n;if(firstCross<0)firstCross=sample;lastCross=sample;++crossings;}previous=value;}}const double pitch=48000.0*(crossings-1)/(lastCross-firstCross);need(std::abs(pitch-442)<.2,"concert A4 tuning applies to sample playback");for(int mode:{1,2}){set(*tuned,"voiceMode",float(mode));set(*tuned,"glideTime",.12f);set(*tuned,"concertPitch",440);tuned->prepareToPlay(48000,128);float prior=0;const auto hz=[&](int blocks,int note){int count=0;for(int block=0;block<blocks;++block){juce::MidiBuffer midi;if(block==0&&note>=0)midi.addEvent(juce::MidiMessage::noteOn(1,note,.8f),0);tuned->processBlock(tunedAudio,midi);for(int n=0;n<128;++n){const float v=tunedAudio.getSample(0,n);if(prior<=0&&v>0)++count;prior=v;}}return count*48000.0/(blocks*128);};hz(80,69);const auto early=hz(8,81);hz(220,-1);const auto late=hz(40,-1);need(early>400&&early<700&&late>820&&late<930,"sample playback supports mono and legato portamento");}fixtureFolder.deleteRecursively();
